  [1785] = { "Il Tome of Divinity", nil, nil, nil, nil, 0xe91f21c0, nil, nil, nil, nil, ".mmmm" },
  [1786] = { "Il Tome of Divinity", nil, nil, nil, nil, 0xe91f21c0, nil, nil, nil, nil, ".mmmm" },
  [1787] = { "Il Tome of Divinity", "Recupera una Defias Script dai Defias Rogue Wizards di Elwynn e torna da Gazin Tenorm a Stormwind.", "Avremo tempo di parlare ancora del Symbol più avanti. Ora l'importante è prendere le carte che abbiamo visto esaminare dai Defias. Se riusciamo a metterci le mani sopra, potremo dimostrare che i Defias si sono infiltrati a Elwynn e, speriamo, capire qualcosa dei loro piani.\n\nPer ora non sono in condizione di combattere, {name}. Pensi di essere abbastanza forte da prendere quelle carte ai Defias qui sull'isola?\n\nSe ci riesci, portale a Gazin e digli che sto bene.", "Henze è al sicuro, {name}? Ci sei <riuscito/riuscita>?\n\nTra la tua abilità con le armi e il potere della Luce, immagino che la Heroes' Vigil sia al sicuro da qualsiasi minaccia dei Defias, ma questo spetta al re e ai suoi consiglieri dirlo.", "Magnifico! Ce l'hai fatta, e hai salvato Henze. La Luce è certamente con te, {name}!", 0xe91f21c0, 0x09e322c6, 0xb07e8693, 0x78c1898e, 0x3eda4356, "....." },
  [1788] = { "Il Tome of Divinity", "Parla con Duthorian Rall, a Stormwind.", nil, nil, nil, 0xe91f21c0, 0x0f3ca705, nil, nil, nil, "..mmm" },
  [1793] = { "Il Tome of Valor", nil, nil, nil, nil, 0xdaebf666, nil, nil, nil, nil, ".mmmm" },
  [1794] = { "Il Tome of Valor", nil, nil, nil, nil, 0xdaebf666, nil, nil, nil, nil, ".mmmm" },
  [1860] = { "Parlare con Jennea", "Parla con Jennea Cannon, a Stormwind.", "Noi maghi abbiamo un compito da svolgere, un compito vitale per la sicurezza di Stormwind e della foresta di Elwynn.\n\nJennea Cannon conosce i dettagli. Studia nel santuario dei maghi, nel quartiere dei maghi di Stormwind. Dovresti raggiungerla in fretta.", nil, "Ti hanno mandato ad aiutarmi nel mio compito, {name}? Bene. È confortante vedere giovani maghi ansiosi di aiutare la nostra causa...\n\nQuale causa, chiedi? A tempo debito, giovane. Saprai... a tempo debito.", 0x7b586e0a, 0x17610de7, 0x833e5a0d, nil, 0x5a63396f, "...m." },
  [1919] = { nil, "Parla con Jennea Cannon, a Stormwind.", nil, nil, nil, nil, 0x17610de7, nil, nil, nil, "m.mmm" },
  [1978] = { nil, nil, nil, "Sì?", nil, nil, nil, nil, 0x0c07a888, nil, "mmm.m" },
})
